#!/usr/bin/env python3
"""Build index.html from embedded ARG content on Windows or Linux.

Requires Python 3.10+ and cryptography. Two passwords protect public and full views.
HTML, CSS, the zxing-wasm reader and runtimes are embedded.
"""
from __future__ import annotations

import argparse
import base64
import getpass
import gzip
import hashlib
from html.parser import HTMLParser
import json
import os
from pathlib import Path
import re
import stat
import sys
import tempfile

ITERATIONS = 600_000
SOURCE_NAMES = ("daialy_arg.html", "keyclose_daialy_arg.html", "style.css", "keyclose_style.css")
SECURITY_META = '''<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data: blob:; media-src blob:; connect-src 'none'; base-uri 'none'; form-action 'none'">'''
FIT_STYLE = '<style>.opensite,.closesite{width:min(700px,calc(100% - 32px));overflow-wrap:anywhere}</style>'
# Embedded HTML/CSS, zxing-wasm reader, WASM, licenses and runtimes.
EMBEDDED_ASSETS = ""


def validate_password(password: str) -> None:
    if not password or "\r" in password or "\n" in password:
        raise ValueError("パスワードは空文字・改行なしで入力してください。")


def password_hash(password: str) -> str:
    validate_password(password)
    return hashlib.sha256(password.encode("utf-8")).hexdigest()


class TagAttributes(HTMLParser):
    def __init__(self, tag: str):
        super().__init__()
        self.attributes: dict[str, str | None] = {}
        self.feed(tag)

    def handle_starttag(self, tag, attrs):
        self.attributes = dict(attrs)

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)


def insert_before(html: str, tag: str, content: str) -> str:
    return re.sub(rf"</{tag}\s*>", lambda match: content + "\n" + match[0], html, flags=re.I)


def inline_document(html: str, css: str, stylesheet: str) -> str:
    if re.search(r"<(?:iframe|object|embed)\b|<(?:script|img|source|video|audio)\b[^>]*\bsrc\s*=", html, re.I | re.S) or re.search(r"url\s*\(|@import", css, re.I):
        raise ValueError("外部素材が含まれています。このツールは指定のHTML・CSS 4ファイル用です。")
    for tag in ("html", "head", "body"):
        if not re.search(rf"<{tag}\b", html, re.I) or not re.search(rf"</{tag}\s*>", html, re.I):
            raise ValueError(f"HTMLに {tag} タグがありません。")
    css = re.sub(r'''@charset\s+["'][^"']+["'];?''', "", css, flags=re.I)
    found = 0

    def replace_link(match):
        nonlocal found
        attrs = TagAttributes(match[0]).attributes
        if "stylesheet" not in (attrs.get("rel") or "").lower().split():
            return match[0]
        if attrs.get("href") != stylesheet:
            raise ValueError(f"未対応のCSS参照: {attrs.get('href')}")
        found += 1
        return "<style>" + css + "</style>"

    html = re.sub(r"<link\b[^>]*>", replace_link, html, flags=re.I | re.S)
    if not found:
        raise ValueError(f"{stylesheet} への参照がHTMLに見つかりません。")
    html = re.sub(r"<html\b[^>]*>", '<html lang="ja">', html, flags=re.I)
    viewport = '<meta name="viewport" content="width=device-width, initial-scale=1">'
    html, count = re.subn(r'''<meta\b(?=[^>]*\bname\s*=\s*["']viewport["'])[^>]*>''', viewport, html, flags=re.I | re.S)
    head_content = SECURITY_META + ("" if count else viewport)
    html = re.sub(r"<head\b[^>]*>", lambda match: match[0] + "\n" + head_content, html, count=1, flags=re.I)
    return insert_before(html, "head", FIT_STYLE)


def insert_before_footer(html: str, content: str) -> str:
    result, count = re.subn(r"<footer\b[^>]*>", lambda match: content + "\n" + match[0], html, count=1, flags=re.I)
    if not count:
        raise ValueError("HTMLにfooterタグがありません。")
    return result


def make_html(source: Path | None, entry_password: str, full_password: str) -> str:
    entry_hash, full_hash = password_hash(entry_password), password_hash(full_password)
    if entry_password == full_password:
        raise ValueError("入口QR用と完全版用は、異なるパスワードを指定してください。")
    try:
        from cryptography.hazmat.primitives.ciphers.aead import AESGCM
    except ImportError as error:
        raise RuntimeError("cryptography が必要です。Pythonの -m pip install cryptography を実行してください。") from error

    assets = json.loads(gzip.decompress(base64.b64decode(EMBEDDED_ASSETS)).decode("utf-8"))
    if source is None:
        files = assets["sources"]
    else:
        files = {}
        for name in SOURCE_NAMES:
            file = source / name
            if not file.is_file():
                raise ValueError(f"元ファイルがありません: {file}")
            files[name] = file.read_text(encoding="utf-8-sig")

    def encrypt_document(html: str, password: str) -> dict:
        salt, iv = os.urandom(16), os.urandom(12)
        key = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, ITERATIONS, dklen=32)
        encrypted = AESGCM(key).encrypt(iv, html.encode("utf-8"), None)
        encode = lambda value: base64.b64encode(value).decode("ascii")
        return {"version": 1, "iterations": ITERATIONS, "salt": encode(salt), "iv": encode(iv), "ciphertext": encode(encrypted)}

    compact_json = lambda value: json.dumps(value, separators=(",", ":"))
    secret = inline_document(files[SOURCE_NAMES[1]], files[SOURCE_NAMES[3]], SOURCE_NAMES[3])
    lock = '''<button id="arg-lock" type="button" style="display:block;margin:24px 0;padding:10px;font:inherit;cursor:pointer">入口へ戻る</button><script>document.getElementById("arg-lock").addEventListener("click", () => location.reload());</script>'''
    secret = insert_before_footer(secret, lock)
    full_runtime = (assets["fullRuntime"].replace("__CRYPTO_HELPERS__", assets["cryptoHelpers"])
                    .replace("__FULL_HASH__", json.dumps(full_hash))
                    .replace("__ENCRYPTED_FULL__", compact_json(encrypt_document(secret, full_password))))
    public = inline_document(files[SOURCE_NAMES[0]], files[SOURCE_NAMES[2]], SOURCE_NAMES[2])
    public = public.replace("<!--ここに動的処理-->", '<p><a href="#arg-full-unlock">ページ末尾のパスワード入力へ</a></p>')
    public = insert_before(public, "head", "<style>" + assets["fullStyle"] + "</style>")
    public = insert_before_footer(public, assets["fullMarkup"])
    public = insert_before(public, "body", "<script>" + full_runtime + "</script>")
    entry_runtime = (assets["entryRuntime"].replace("__CRYPTO_HELPERS__", assets["cryptoHelpers"])
                     .replace("__ENTRY_HASH__", json.dumps(entry_hash))
                     .replace("__ENCRYPTED_PUBLIC__", compact_json(encrypt_document(public, entry_password)))
                     .replace("__QR_WASM_BINARY__", json.dumps(assets["qrWasm"])))
    library = re.sub(r"</script", lambda match: r"<\/script", assets["qrLibrary"], flags=re.I)
    wasm_meta = SECURITY_META.replace("script-src 'unsafe-inline'", "script-src 'unsafe-inline' 'wasm-unsafe-eval'")
    return ('<!doctype html>\n<html lang="ja"><head><meta charset="utf-8">'
            '<meta name="viewport" content="width=device-width, initial-scale=1">'
            + wasm_meta + '<title>QRコード</title><style>' + assets["entryStyle"] + '</style></head><body>'
            + assets["entryMarkup"] + '\n<!--\n' + assets["license"] + '\n-->\n<script>' + library
            + '</script>\n<script>' + entry_runtime + '</script></body></html>')


def build_index(source: Path | None, output_directory: Path, entry_password: str, full_password: str) -> Path:
    # Generate fully before replacing the existing file.
    html = make_html(source, entry_password, full_password)
    output_directory.mkdir(parents=True, exist_ok=True)
    target = output_directory / "index.html"
    mode = stat.S_IMODE(target.stat().st_mode) if target.exists() else 0o644
    temporary: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", newline="\n", prefix=".index-", suffix=".tmp", dir=output_directory, delete=False) as stream:
            temporary = Path(stream.name)
            stream.write(html)
            stream.flush()
            os.fsync(stream.fileno())
        temporary.chmod(mode)
        os.replace(temporary, target)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)
    return target


def main(argv: list[str] | None = None) -> int:
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, "reconfigure"):
            stream.reconfigure(encoding="utf-8", errors="backslashreplace")
    parser = argparse.ArgumentParser(description="入口QR→公開版→完全版の2段階認証HTMLをビルドします。")
    parser.add_argument("--source-dir", type=Path, help="任意: 内蔵内容の代わりに外部の4ファイルを読む。未指定なら外部ファイル不要")
    parser.add_argument("--output-dir", type=Path, help="出力フォルダー（既定: このスクリプトと同じ場所、外部ソース指定時はその場所）。出力名はindex.html")
    parser.add_argument("--hash-only", action="store_true", help="SHA-256だけを表示し、ビルドしない")
    parser.add_argument("--password-stdin", action="store_true", help="--hash-only用。パスワードを標準入力からUTF-8で読む")
    parser.add_argument("--passwords-stdin", action="store_true", help='2つのパスワードをUTF-8 JSON {"entry":"...","full":"..."} で標準入力から読む')
    args = parser.parse_args(argv)
    if args.password_stdin and (not args.hash_only or args.passwords_stdin):
        parser.error("ビルドには --passwords-stdin を使って2つのパスワードを指定してください。")
    if args.hash_only and args.passwords_stdin:
        parser.error("--hash-only と --passwords-stdin は同時に指定できません。")
    try:
        if args.hash_only:
            password = sys.stdin.buffer.read().decode("utf-8") if args.password_stdin else getpass.getpass("パスワードを入力して Enter: ")
            value = password_hash(password)
            print(value)
            print(f'const EXPECTED_PASSWORD_HASH = "{value}";')
        else:
            if args.passwords_stdin:
                passwords = json.loads(sys.stdin.buffer.read().decode("utf-8"))
                if not isinstance(passwords, dict) or not all(isinstance(passwords.get(name), str) for name in ("entry", "full")):
                    raise ValueError('JSONに文字列の "entry" と "full" を指定してください。')
                entry_password, full_password = passwords["entry"], passwords["full"]
            else:
                entry_password = getpass.getpass("1. 入口QR用パスワード: ")
                full_password = getpass.getpass("2. 完全版用パスワード（入口とは別のもの）: ")
            source = args.source_dir.expanduser().resolve() if args.source_dir else None
            output = args.output_dir.expanduser().resolve() if args.output_dir else (source or Path(__file__).resolve().parent)
            print(f"更新しました: {build_index(source, output, entry_password, full_password)}")
        return 0
    except (ValueError, OSError, RuntimeError, EOFError) as error:
        print(f"エラー: {error}", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        print("\n中止しました。", file=sys.stderr)
        return 130


if __name__ == "__main__":
    raise SystemExit(main())
